import { useCallback, useEffect, useState, type ReactNode } from 'react'
import { Activity, Box, Check, CircleAlert, Database, Download, FileCode2, HardDrive, LoaderCircle, Network, Pause, Play, Plus, Power, RefreshCw, RotateCw, Search, Sparkles, Square, TerminalSquare, Trash2, Waypoints } from 'lucide-react'
import { api, formatBytes } from './lib/api'
import { cachedRequest, cachedSnapshot, invalidateCached } from './lib/heavy-cache'
import { Button } from './components/ui/button'
import { Input } from './components/ui/input'
import { Badge } from './components/ui/badge'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from './components/ui/card'
import { Alert, AlertDescription } from './components/ui/alert'
import { Skeleton } from './components/ui/skeleton'
import { MetricCard } from './components/ui/metric-card'
import { useConfirmDialog } from './hooks/useConfirmDialog'
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from './components/ui/dialog'
import { UnifiedStepper } from './components/ui/stepper'
import { Tabs, TabsContent, TabsList, TabsTrigger } from './components/ui/tabs'

type DockerContainer = { id: string; names: string; image: string; status: string; ports: string; state: string; application_id?: string; stats?: { cpu?: string; memory?: string; memory_percent?: string; network_io?: string; block_io?: string } }
type DockerImage = { id: string; repository: string; tag: string; size: string; created: string }
type DockerNetworkMember = { id: string; name: string; ipv4?: string; ipv6?: string; application_id?: string }
type DockerNetwork = { id: string; name: string; driver: string; scope: string; internal?: boolean; containers?: DockerNetworkMember[]; details_available?: boolean }
type DockerVolume = { name: string; driver: string; mountpoint: string }
type DockerData = { installed: boolean; active: boolean; version: string; server_version?: string; compose_version?: string; compose_projects?: Array<{ Name?: string; Status?: string; ConfigFiles?: string }>; containers: DockerContainer[]; images: DockerImage[]; networks: DockerNetwork[]; volumes: DockerVolume[]; error?: string }
type OptimizationData = { measured_at: number; docker: { available: boolean; build_cache_bytes: number; images_bytes: number; containers_bytes: number; volumes_bytes: number; error: string }; arg_cache: { reclaimable_bytes: number; protected_mounts: number }; logs: { journal_bytes: number; journal_reclaimable_bytes: number; rotated_reclaimable_bytes: number; retention_days: number; error: string }; apt_cache_bytes: number }
type Heading = (props: { title: string; description: string; action?: ReactNode }) => ReactNode
type DockerApp = { id: string; name: string; source_type: string }

const tabs = [
  { id: 'containers', label: 'کانتینرها', icon: Box },
  { id: 'images', label: 'ایمیج‌ها', icon: Download },
  { id: 'networks', label: 'شبکه‌ها', icon: Network },
  { id: 'volumes', label: 'Volumeها', icon: Database },
  { id: 'compose', label: 'Compose', icon: FileCode2 },
  { id: 'topology', label: 'توپولوژی شبکه', icon: Waypoints },
] as const

type DockerPageProps = { Heading: Heading; notify: (message: string) => void; optimizationOnly?: boolean }

export function DockerOptimizationPage(props: Omit<DockerPageProps, 'optimizationOnly'>) {
  return <DockerPage {...props} optimizationOnly />
}

export function DockerPage({ Heading, notify, optimizationOnly = false }: DockerPageProps) {
  const [data, setData] = useState<DockerData | null>(() => cachedSnapshot('docker'))
  const [tab, setTab] = useState<(typeof tabs)[number]['id']>('containers')
  const [optimization, setOptimization] = useState<OptimizationData | null>(null)
  const [optimizationLoading, setOptimizationLoading] = useState(false)
  const [optimizationError, setOptimizationError] = useState('')
  const [retentionDays, setRetentionDays] = useState<7 | 30 | 90>(30)
  const [loading, setLoading] = useState(() => !cachedSnapshot('docker'))
  const [refreshing, setRefreshing] = useState(false)
  const [busy, setBusy] = useState('')
  const [error, setError] = useState('')
  const [output, setOutput] = useState('')
  const [containerName, setContainerName] = useState('')
  const [applicationId, setApplicationId] = useState('')
  const [dockerApps, setDockerApps] = useState<DockerApp[]>([])
  const [image, setImage] = useState('')
  const [ports, setPorts] = useState('')
  const [env, setEnv] = useState('')
  const [network, setNetwork] = useState('')
  const [restart, setRestart] = useState('unless-stopped')
  const [memoryLimitMb, setMemoryLimitMb] = useState('')
  const [cpuLimit, setCpuLimit] = useState('')
  const [internalNetwork, setInternalNetwork] = useState(false)
  const [imageQuery, setImageQuery] = useState('')
  const [pullImage, setPullImage] = useState('')
  const [buildTag, setBuildTag] = useState('local/my-app:latest')
  const [buildContext, setBuildContext] = useState('/opt/arg/docker-builds/my-app')
  const [tagSource, setTagSource] = useState('')
  const [tagDestination, setTagDestination] = useState('')
  const [execCommand, setExecCommand] = useState('')
  const [resourceName, setResourceName] = useState('')
  const [composeFile, setComposeFile] = useState('/opt/arg/compose/docker-compose.yml')
  const [composeWizardOpen, setComposeWizardOpen] = useState(false)
  const [composeWizardStep, setComposeWizardStep] = useState(0)
  const [composeAction, setComposeAction] = useState<'compose-pull' | 'compose-up' | 'compose-down'>('compose-up')
  const [composeDownAcknowledged, setComposeDownAcknowledged] = useState(false)
  const { confirm, confirmDialog } = useConfirmDialog()

  const load = useCallback(async (force = false) => {
    setError('')
    try { setData(await cachedRequest('docker', () => api<DockerData>('docker'), 120000, force)) }
    catch (cause) { setError(cause instanceof Error ? cause.message : 'وضعیت Docker دریافت نشد.') }
    finally { setLoading(false); setRefreshing(false) }
  }, [])
  const loadOptimization = useCallback(async () => {
    setOptimizationError('')
    setOptimizationLoading(true)
    try { setOptimization(await api<OptimizationData>(`docker/optimization?retention_days=${retentionDays}`)) }
    catch (cause) { setOptimizationError(cause instanceof Error ? cause.message : 'برآورد پاک‌سازی دریافت نشد.') }
    finally { setOptimizationLoading(false) }
  }, [retentionDays])
  useEffect(() => { void load() }, [load])
  useEffect(() => { if (!optimizationOnly) void api<{ apps: DockerApp[] }>('apps').then((result) => setDockerApps(result.apps.filter((app) => app.source_type === 'docker'))).catch(() => setDockerApps([])) }, [optimizationOnly])
  useEffect(() => { if (optimizationOnly) void loadOptimization() }, [optimizationOnly, loadOptimization])
  useEffect(() => { if (!optimizationOnly && data && !data.installed) void loadOptimization() }, [optimizationOnly, data, loadOptimization])

  async function run(action: string, payload: Record<string, unknown> = {}, confirmation?: string, alreadyConfirmed = false): Promise<boolean> {
    if (busy) return false
    const target = typeof payload.target === 'string' ? payload.target : ''
    const targetContainer = target ? data?.containers.find((item) => item.id === target || item.id.startsWith(target) || item.names === target) : undefined
    const ownerApp = targetContainer?.application_id ? dockerApps.find((app) => app.id === targetContainer.application_id) : undefined
    const isReadOnlyContainerAction = action === 'container-logs' || action === 'container-inspect'
    const ownershipWarning = targetContainer?.application_id && !isReadOnlyContainerAction
      ? `این کانتینر${ownerApp ? ` متعلق به اپلیکیشن «${ownerApp.name}»` : ' تحت مدیریت اپلیکیشن‌منیجر'} است. تغییر دستی ممکن است با Deploy یا تنظیمات بعدی اپلیکیشن بازنویسی شود${ownerApp ? `؛ مدیریت اپ: #/apps?app=${ownerApp.id}` : ''}.`
      : ''
    const confirmationText = [ownershipWarning, confirmation].filter(Boolean).join('\n\n')
    if (confirmationText && !alreadyConfirmed && !await confirm({ title: `تأیید عملیات Docker: ${action}`, description: confirmationText, destructive: /remove|prune|down|uninstall|clean/i.test(action), confirmLabel: 'تأیید و اجرا' })) return false
    setBusy(action); setError(''); setOutput('')
    try {
      const result = await api<{ output: string }>('docker/action', { method: 'POST', body: JSON.stringify({ action, ...payload, confirmed: !!confirmationText }) })
      invalidateCached('docker')
      setOutput(result.output || 'Operation completed successfully.')
      notify(`عملیات Docker (${action}) انجام شد.`)
      if (!optimizationOnly) await load(true)
      if (action.includes('prune') || action === 'apt-cache-clean') await loadOptimization()
      return true
    } catch (cause) {
      const message = cause instanceof Error ? cause.message : 'عملیات Docker ناموفق بود.'
      setError(message); notify(message)
      return false
    } finally { setBusy('') }
  }
  function openComposeWizard(action: 'compose-pull' | 'compose-up' | 'compose-down') {
    setComposeAction(action); setComposeWizardStep(0); setComposeDownAcknowledged(false); setComposeWizardOpen(true)
  }
  async function executeComposeWizard() {
    const warning = composeAction === 'compose-down' ? 'سرویس‌های تعریف‌شده متوقف و کانتینرهایشان حذف می‌شوند؛ Volumeها نگه داشته می‌شوند.' : undefined
    if (await run(composeAction, { compose_file: composeFile }, warning, true)) setComposeWizardOpen(false)
  }
  const refresh = () => { setRefreshing(true); void load(true) }
  const ready = !!data?.installed && !!data.active
  const count = (value: number) => value.toLocaleString('en-US')
  const disabled = !!busy || !ready
  const operationButton = (action: string, target: string, label: string, Icon: typeof Play, confirmation?: string) => <Button key={action} size="sm" variant="outline" disabled={!!busy || !ready} onClick={() => void run(action, { target }, confirmation)}><Icon size={13}/>{label}{busy === action && <LoaderCircle size={13} className="animate-spin"/>}</Button>
  const visibleImages = (data?.images || []).filter((item) => `${item.repository}:${item.tag} ${item.id}`.toLowerCase().includes(imageQuery.toLowerCase()))

  if (optimizationOnly && loading) return <><Heading title="بهینه‌سازی سرور" description="در حال بررسی فضای قابل‌بازیابی و وضعیت Docker…"/><div className="mb-5 grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{Array.from({ length: 4 }, (_, index) => <Skeleton key={index} className="h-24 rounded-2xl"/>)}</div><Skeleton className="h-80 rounded-2xl"/></>
  if (loading) return <><Heading title="مدیریت Docker" description="در حال بررسی سرویس Docker و منابع کانتینری سرور…"/><div className="mb-5 grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{Array.from({ length: 4 }, (_, index) => <Skeleton key={index} className="h-24 rounded-2xl"/>)}</div><Skeleton className="h-80 rounded-2xl"/></>

  if (optimizationOnly) return <>
    <Heading title="بهینه‌سازی سرور" description="فضای قابل‌بازیابی Docker و فایل‌های میزبان را بررسی و پاک‌سازی‌ها را جداگانه مدیریت کن." action={<Button size="sm" variant="outline" disabled={refreshing || optimizationLoading || !!busy} onClick={() => { setRefreshing(true); void Promise.all([load(true), loadOptimization()]).finally(() => setRefreshing(false)) }}><RefreshCw size={14} className={refreshing || optimizationLoading ? 'animate-spin' : ''}/>محاسبهٔ دوباره</Button>}/>
    {error && <Alert className="mb-4 border-amber-300/20 bg-amber-300/[.04]"><CircleAlert size={15}/><AlertDescription>{error}</AlertDescription></Alert>}
    <DockerOptimizationPanel optimization={optimization} loading={optimizationLoading} error={optimizationError} retentionDays={retentionDays} setRetentionDays={setRetentionDays} refresh={loadOptimization} run={run} busy={busy} dockerReady={ready}/>
    {output && <Card className="mt-5"><CardHeader className="pb-2"><CardTitle className="text-sm">گزارش آخرین عملیات</CardTitle></CardHeader><CardContent><pre className="max-h-56 overflow-auto whitespace-pre-wrap break-words rounded-xl bg-[#090d12] p-3 text-left font-mono text-xs text-muted-foreground" dir="ltr">{output}</pre></CardContent></Card>}
    {confirmDialog}
  </>

  return <>
    <Heading title="مدیریت Docker" description="سرویس Docker، کانتینرها، ایمیج‌ها، شبکه‌ها، volumeها و پروژه‌های Compose را مدیریت کن." action={<div className="flex flex-wrap gap-2"><Button size="sm" variant="outline" disabled={!!busy || refreshing} onClick={refresh}><RefreshCw size={14} className={refreshing ? 'animate-spin' : ''}/>تازه‌سازی</Button>{data?.installed && <Button size="sm" variant="outline" disabled={!!busy} onClick={() => void run('restart', {}, 'سرویس Docker دوباره راه‌اندازی شود؟ کانتینرها ممکن است موقتاً قطع شوند.')}><RotateCw size={14}/>راه‌اندازی مجدد</Button>}</div>}/>
    {error && <Alert className="mb-5 border-rose-400/25 bg-rose-400/[.06]"><CircleAlert size={16}/><AlertDescription>{error}</AlertDescription></Alert>}
    {!data?.installed ? <Card className="mb-5 overflow-hidden border-primary/20 bg-gradient-to-br from-primary/[.08] to-card"><CardHeader><CardTitle className="flex items-center gap-2"><Box className="text-primary"/>Docker نصب نشده است</CardTitle><CardDescription>نصب Docker Engine از مخازن APT سیستم انجام می‌شود. بعد از نصب، سرویس فعال و هنگام بوت راه‌اندازی خواهد شد.</CardDescription></CardHeader><CardContent><Button disabled={!!busy} onClick={() => void run('install')}><Download size={15}/>{busy === 'install' ? 'در حال نصب Docker…' : 'نصب Docker Engine'}{busy === 'install' && <LoaderCircle size={14} className="animate-spin"/>}</Button></CardContent></Card> : <>
      {data.error && <Alert className="mb-5 border-amber-300/20 bg-amber-300/[.04]"><CircleAlert size={16}/><AlertDescription>بخشی از فهرست منابع دریافت نشد: {data.error}</AlertDescription></Alert>}
      <div className="mb-5 grid gap-3 sm:grid-cols-2 xl:grid-cols-4">
        <MetricCard label="سرویس Docker" value={ready ? 'فعال' : 'متوقف'} detail={data.server_version ? `Engine ${data.server_version}` : 'نیاز به راه‌اندازی سرویس'} icon={<Power size={18}/>} tone={ready ? 'green' : 'warning'} direction="rtl"/>
        <MetricCard label="کانتینرها" value={count(data.containers.length)} detail={`${count(data.containers.filter((item) => item.state === 'running').length)} در حال اجرا`} icon={<Box size={18}/>} tone="copper"/>
        <MetricCard label="Imageهای محلی" value={count(data.images.length)} detail="آمادهٔ اجرا یا حذف در صورت بلااستفاده بودن" icon={<Download size={18}/>} tone="blue"/>
        <MetricCard label="Volumeهای پایدار" value={count(data.volumes.length)} detail="داده با حذف کانتینر پاک نمی‌شود" icon={<HardDrive size={18}/>} tone="teal"/>
      </div>
      {!ready && <Card className="mb-5 border-amber-300/20 bg-amber-300/[.04]"><CardContent className="flex flex-wrap items-center justify-between gap-3 p-4"><div><p className="font-medium text-amber-100">Docker daemon در دسترس نیست</p><p className="mt-1 text-xs text-muted-foreground">{data.error || 'سرویس را شروع کن تا منابع Docker بارگذاری شوند.'}</p></div><div className="flex gap-2"><Button size="sm" disabled={!!busy} onClick={() => void run('start')}><Play size={14}/>شروع سرویس</Button><Button size="sm" variant="outline" disabled={!!busy} onClick={() => void run('enable')}><Check size={14}/>فعال هنگام بوت</Button></div></CardContent></Card>}
      <Tabs value={tab} onValueChange={(value) => setTab(value as (typeof tabs)[number]['id'])} dir="rtl">
        <TabsList aria-label="بخش‌های مدیریت Docker">{tabs.map((item) => <TabsTrigger key={item.id} value={item.id}><item.icon size={14}/>{item.label}</TabsTrigger>)}</TabsList>

      <TabsContent value="containers" className="space-y-5">
        <Card><CardHeader><CardTitle className="flex items-center gap-2"><Plus size={17} className="text-primary"/>ساخت و اجرای کانتینر</CardTitle><CardDescription>تنظیمات شبکه، restart و سقف CPU/RAM را پیش از اجرا تعیین کن؛ محدودیت منابع برای جلوگیری از اشغال کامل سرور در دسترس است.</CardDescription></CardHeader><CardContent><form className="grid gap-3 md:grid-cols-2 xl:grid-cols-3" onSubmit={(event) => { event.preventDefault(); void run('container-run', { name: containerName, image, ports: ports.split(/[\s,]+/).filter(Boolean), env: env.split('\n').map((line) => line.trim()).filter(Boolean), network, restart, application_id: applicationId || undefined, memory_limit_mb: memoryLimitMb ? Number(memoryLimitMb) : undefined, cpu_limit: cpuLimit ? Number(cpuLimit) : undefined }); }}>
          <label className="space-y-1.5 text-xs"><span>نام کانتینر</span><Input required value={containerName} onChange={(event) => setContainerName(event.target.value)} placeholder="web-app" dir="ltr"/></label>
          <label className="space-y-1.5 text-xs"><span>Image</span><Input required value={image} onChange={(event) => setImage(event.target.value)} placeholder="nginx:alpine" dir="ltr"/></label>
          <label className="space-y-1.5 text-xs"><span>نگاشت پورت</span><Input value={ports} onChange={(event) => setPorts(event.target.value)} placeholder="8080:80/tcp, 5353:53/udp" dir="ltr"/><span className="block text-[10px] text-muted-foreground">هر نگاشت را با فاصله یا کاما جدا کن.</span></label>
          <label className="space-y-1.5 text-xs"><span>شبکه (اختیاری)</span><Input value={network} onChange={(event) => setNetwork(event.target.value)} placeholder="bridge" dir="ltr"/></label>
          <label className="space-y-1.5 text-xs"><span>سیاست راه‌اندازی مجدد</span><select className="h-10 w-full rounded-lg border border-input bg-background px-3 text-sm" value={restart} onChange={(event) => setRestart(event.target.value)}><option value="unless-stopped">unless-stopped</option><option value="always">always</option><option value="on-failure">on-failure</option><option value="no">no</option></select></label>
          <label className="space-y-1.5 text-xs"><span>سقف حافظه (MB، اختیاری)</span><Input type="number" min={16} max={1048576} step={16} value={memoryLimitMb} onChange={(event) => setMemoryLimitMb(event.target.value)} placeholder="مثلاً 512" dir="ltr"/><span className="block text-[10px] text-muted-foreground">بین 16 MB تا 1 TB؛ خالی یعنی بدون محدودیت.</span></label>
          <label className="space-y-1.5 text-xs"><span>سقف CPU بر حسب هسته (اختیاری)</span><Input type="number" min={0.1} max={128} step={0.1} value={cpuLimit} onChange={(event) => setCpuLimit(event.target.value)} placeholder="مثلاً 1.5" dir="ltr"/><span className="block text-[10px] text-muted-foreground">بین 0.1 تا 128 هسته؛ خالی یعنی بدون محدودیت.</span></label>
          <label className="space-y-1.5 text-xs"><span>اپ ARG (اختیاری)</span><select className="h-10 w-full rounded-lg border border-input bg-background px-3 text-sm" value={applicationId} onChange={(event) => setApplicationId(event.target.value)}><option value="">بدون پیوند به اپ</option>{dockerApps.map((app) => <option key={app.id} value={app.id}>{app.name}</option>)}</select><span className="block text-[10px] text-muted-foreground">پیوند مالکیت برای عضویت کنترل‌شده در شبکهٔ خصوصی اپ.</span></label>
          <label className="space-y-1.5 text-xs md:col-span-2 xl:col-span-3"><span>متغیرهای محیطی (هر خط KEY=VALUE)</span><textarea value={env} onChange={(event) => setEnv(event.target.value)} dir="ltr" className="min-h-20 w-full rounded-lg border border-input bg-background p-3 text-left font-mono text-xs outline-none focus:ring-2 focus:ring-ring" placeholder={'NODE_ENV=production\nPORT=3000'}/></label>
          <div className="md:col-span-2 xl:col-span-3"><Button type="submit" disabled={disabled}><Play size={14}/>{busy === 'container-run' ? 'در حال ساخت…' : 'ساخت و اجرا'}</Button></div>
        </form></CardContent></Card>
        <Card><CardHeader className="flex-row items-center justify-between gap-3"><div><CardTitle>کانتینرها</CardTitle><CardDescription>وضعیت اجرا و عملیات روی هر کانتینر؛ آمار از docker stats خوانده می‌شود.</CardDescription></div><Badge variant="outline">{count(data.containers.length)}</Badge></CardHeader><CardContent><div className="space-y-2">{data.containers.map((item) => <details key={item.id} className="group rounded-xl border border-border bg-background/40 open:bg-card"><summary className="flex cursor-pointer list-none flex-wrap items-center gap-3 p-3"><span className={`h-2 w-2 rounded-full ${item.state === 'running' ? 'bg-emerald-400' : item.state === 'paused' ? 'bg-amber-400' : 'bg-slate-500'}`}/><span className="min-w-48 flex-1"><b dir="ltr" className="block text-left font-mono text-xs">{item.names}</b><span dir="ltr" className="mt-1 block truncate text-left text-[11px] text-muted-foreground">{item.image}</span></span><Badge variant={item.state === 'running' ? 'success' : item.state === 'exited' ? 'outline' : 'warning'}>{item.status || item.state}</Badge>{item.application_id && <Badge variant="outline" className="border-amber-300/30 text-amber-200">مدیریت‌شده در اپ‌منیجر</Badge>}{item.stats && <code dir="ltr" className="text-[10px] text-muted-foreground">CPU {item.stats.cpu} · RAM {item.stats.memory} ({item.stats.memory_percent})</code>}<code dir="ltr" className="max-w-full truncate text-[10px] text-muted-foreground">{item.ports || 'بدون پورت منتشرشده'}</code></summary><div className="border-t border-border/70 p-3">{item.application_id && <Alert className="mb-3 border-amber-300/25 bg-amber-300/[.05]"><CircleAlert size={15} className="text-amber-300"/><AlertDescription className="flex flex-wrap items-center gap-x-1 gap-y-1 text-amber-100">این کانتینر تحت مدیریت اپلیکیشن‌منیجر است؛ تغییر دستی ممکن است با Deploy بعدی بازنویسی شود.{dockerApps.find((app) => app.id === item.application_id) && <Button type="button" variant="link" size="sm" className="h-auto p-0 text-amber-200" onClick={() => { window.location.hash = `#/apps?app=${item.application_id}` }}>رفتن به مدیریت اپلیکیشن</Button>}</AlertDescription></Alert>}{item.stats && <p dir="ltr" className="mb-3 flex flex-wrap gap-x-4 gap-y-1 text-left font-mono text-[10px] text-muted-foreground"><span>Network I/O: {item.stats.network_io}</span><span>Block I/O: {item.stats.block_io}</span></p>}<div className="flex flex-wrap gap-2">{item.state === 'running' ? <>{operationButton('container-stop', item.id, 'توقف', Square, 'این کانتینر متوقف شود؟')}{operationButton('container-restart', item.id, 'راه‌اندازی مجدد', RotateCw, 'کانتینر دوباره راه‌اندازی شود؟')}{operationButton('container-pause', item.id, 'مکث', Pause)}</> : <>{operationButton('container-start', item.id, 'شروع', Play)}{item.state === 'paused' && operationButton('container-unpause', item.id, 'ادامه', Play)}</>}{operationButton('container-logs', item.id, 'لاگ‌ها', TerminalSquare)}{operationButton('container-inspect', item.id, 'جزئیات inspect', Search)}{operationButton('container-remove', item.id, 'حذف کانتینر', Trash2, `کانتینر ${item.names} به‌همراه writable layer آن حذف شود؟ volumeهای متصل باقی می‌مانند.`)}</div>{item.state === 'running' && <form className="mt-3 flex flex-wrap gap-2 border-t border-border/70 pt-3" onSubmit={(event) => { event.preventDefault(); void run('container-exec', { target: item.id, command: execCommand.trim().split(/\s+/).filter(Boolean) }); }}><Input className="min-w-48 flex-1 font-mono" value={execCommand} onChange={(event) => setExecCommand(event.target.value)} placeholder="دستور و آرگومان‌ها، مثال: nginx -t" dir="ltr" required/><Button size="sm" variant="outline" disabled={!!busy}><TerminalSquare size={13}/>اجرای دستور در کانتینر</Button></form>}</div></details>)}{!data.containers.length && <p className="rounded-xl border border-dashed border-border p-8 text-center text-sm text-muted-foreground">هنوز کانتینری ساخته نشده است.</p>}</div></CardContent></Card>
      </TabsContent>

      <TabsContent value="images" className="space-y-5"><Card><CardHeader><CardTitle>دریافت یا ساخت Image</CardTitle><CardDescription>image را از registry بگیر یا از مسیر دارای Dockerfile بساز.</CardDescription></CardHeader><CardContent><div className="grid gap-5 lg:grid-cols-2"><form className="flex flex-wrap content-start gap-2" onSubmit={(event) => { event.preventDefault(); void run('image-pull', { image: pullImage }); }}><Input className="min-w-48 flex-1" value={pullImage} onChange={(event) => setPullImage(event.target.value)} placeholder="nginx:alpine" dir="ltr" required/><Button disabled={disabled}><Download size={14}/>{busy === 'image-pull' ? 'در حال دریافت…' : 'Pull image'}</Button></form><form className="grid gap-2 sm:grid-cols-2" onSubmit={(event) => { event.preventDefault(); void run('image-build', { image: buildTag, context_path: buildContext }); }}><Input value={buildTag} onChange={(event) => setBuildTag(event.target.value)} placeholder="local/my-app:latest" dir="ltr" required/><Input value={buildContext} onChange={(event) => setBuildContext(event.target.value)} placeholder="/opt/arg/docker-builds/my-app" dir="ltr" required/><p className="text-[10px] text-muted-foreground sm:col-span-2">مسیر باید پوشهٔ موجود و دارای فایل Dockerfile باشد.</p><Button className="sm:col-span-2" disabled={disabled}><Box size={14}/>{busy === 'image-build' ? 'در حال ساخت image…' : 'Build image'}</Button></form></div></CardContent></Card><Card><CardHeader className="flex-row items-center justify-between gap-3"><div><CardTitle>Imageهای محلی</CardTitle><CardDescription>حذف فقط imageهای بدون وابستگی ممکن است.</CardDescription></div><Badge variant="outline">{count(data.images.length)}</Badge></CardHeader><CardContent><form className="mb-4 grid gap-2 sm:grid-cols-2" onSubmit={(event) => { event.preventDefault(); void run('image-tag', { target: tagSource, image: tagDestination }); }}><Input value={tagSource} onChange={(event) => setTagSource(event.target.value)} placeholder="Source image یا ID" dir="ltr" required/><div className="flex gap-2"><Input className="min-w-0 flex-1" value={tagDestination} onChange={(event) => setTagDestination(event.target.value)} placeholder="registry/user/app:tag" dir="ltr" required/><Button size="sm" variant="outline" disabled={disabled}>Tag</Button></div></form><div className="mb-3 flex flex-wrap items-center gap-2"><div className="relative min-w-48 flex-1"><Search size={14} className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground"/><Input className="pr-9" value={imageQuery} onChange={(event) => setImageQuery(event.target.value)} placeholder="جست‌وجوی image…"/></div><Button size="sm" variant="outline" disabled={disabled} onClick={() => void run('image-prune', {}, 'تمام imageهای بدون استفاده حذف شوند؟ این عملیات قابل بازگشت نیست.')}><Trash2 size={13}/>پاک‌سازی بدون استفاده</Button></div><div className="space-y-2">{visibleImages.map((item, index) => <div key={`${item.id}-${index}`} className="flex flex-wrap items-center gap-3 rounded-xl border border-border bg-background/40 p-3"><Download size={15} className="text-sky-300"/><div className="min-w-48 flex-1"><b dir="ltr" className="block truncate text-left font-mono text-xs">{item.repository}:{item.tag}</b><span dir="ltr" className="mt-1 block text-left font-mono text-[10px] text-muted-foreground">{item.id.slice(0, 19)} · {item.size} · {item.created}</span></div><Button size="sm" variant="outline" disabled={!!busy} onClick={() => void run('image-push', { target: `${item.repository}:${item.tag}` }, `Image ${item.repository}:${item.tag} در registry پیش‌فرض منتشر شود؟`)}><Download size={13}/>Push</Button><Button size="sm" variant="ghost" disabled={!!busy} onClick={() => void run('image-remove', { target: item.id }, `Image ${item.repository}:${item.tag} حذف شود؟`)}><Trash2 size={13}/>حذف</Button></div>)}{!visibleImages.length && <p className="rounded-xl border border-dashed border-border p-8 text-center text-sm text-muted-foreground">Imageی برای نمایش پیدا نشد.</p>}</div></CardContent></Card></TabsContent>

      <TabsContent value="networks"><Card><CardHeader><CardTitle>شبکه‌های Docker</CardTitle><CardDescription>شبکهٔ bridge اختصاصی بساز؛ گزینهٔ Internal دسترسی بیرونی شبکه را ایزوله می‌کند.</CardDescription></CardHeader><CardContent><form className="mb-4 flex flex-wrap items-center gap-3" onSubmit={(event) => { event.preventDefault(); void run('network-create', { name: resourceName, internal: internalNetwork }); setResourceName(''); }}><Input className="min-w-48 flex-1" value={resourceName} onChange={(event) => setResourceName(event.target.value)} placeholder="نام شبکهٔ جدید" dir="ltr" required/><label className="flex items-center gap-2 text-xs text-muted-foreground"><input type="checkbox" checked={internalNetwork} onChange={(event) => setInternalNetwork(event.target.checked)} className="accent-primary"/>شبکهٔ داخلی و بدون خروجی</label><Button disabled={disabled}><Plus size={14}/>ساخت شبکه</Button></form><div className="space-y-2">{data.networks.map((item) => <div key={item.id} className="flex flex-wrap items-center gap-3 rounded-xl border border-border bg-background/40 p-3"><Network size={16} className="text-primary"/><div className="min-w-40 flex-1"><b dir="ltr" className="block text-left font-mono text-xs">{item.name}</b><span className="text-[10px] text-muted-foreground">{item.driver} · {item.scope} · {item.internal ? 'internal' : 'دسترسی عادی'} · <code dir="ltr">{item.id.slice(0, 12)}</code></span><span className="mt-1 block text-[10px] text-muted-foreground">{item.details_available === false ? 'اعضای شبکه در دسترس نیستند' : `${item.containers?.length || 0} کانتینر متصل`}</span></div>{!['bridge', 'host', 'none'].includes(item.name) && <Button size="sm" variant="ghost" disabled={!!busy} onClick={() => void run('network-remove', { target: item.name }, `شبکهٔ ${item.name} حذف شود؟ فقط شبکهٔ بدون اتصال قابل حذف است.`)}><Trash2 size={13}/>حذف</Button>}</div>)}{!data.networks.length && <p className="rounded-xl border border-dashed border-border p-8 text-center text-sm text-muted-foreground">شبکه‌ای پیدا نشد.</p>}</div></CardContent></Card></TabsContent>

      <TabsContent value="volumes"><Card><CardHeader><CardTitle>Volumeهای پایدار</CardTitle><CardDescription>Volumeها با حذف کانتینر پاک نمی‌شوند؛ حذف آن‌ها دادهٔ ذخیره‌شده را از بین می‌برد.</CardDescription></CardHeader><CardContent><form className="mb-4 flex flex-wrap gap-2" onSubmit={(event) => { event.preventDefault(); void run('volume-create', { name: resourceName }); setResourceName(''); }}><Input className="min-w-48 flex-1" value={resourceName} onChange={(event) => setResourceName(event.target.value)} placeholder="نام volume جدید" dir="ltr" required/><Button disabled={disabled}><Plus size={14}/>ساخت volume</Button><Button type="button" size="sm" variant="outline" disabled={disabled} onClick={() => void run('volume-prune', {}, 'تمام volumeهای استفاده‌نشده حذف شوند؟ ممکن است داده‌های پایدار پاک شوند.')}><Trash2 size={13}/>پاک‌سازی بدون استفاده</Button></form><div className="space-y-2">{data.volumes.map((item) => <div key={item.name} className="flex flex-wrap items-center gap-3 rounded-xl border border-border bg-background/40 p-3"><Database size={16} className="text-[#dda46f]"/><div className="min-w-48 flex-1"><b dir="ltr" className="block text-left font-mono text-xs">{item.name}</b><span dir="ltr" className="mt-1 block truncate text-left text-[10px] text-muted-foreground">{item.driver} · {item.mountpoint}</span></div><Button size="sm" variant="ghost" disabled={!!busy} onClick={() => void run('volume-remove', { target: item.name }, `Volume ${item.name} و همهٔ داده‌های داخل آن حذف شود؟`)}><Trash2 size={13}/>حذف</Button></div>)}{!data.volumes.length && <p className="rounded-xl border border-dashed border-border p-8 text-center text-sm text-muted-foreground">Volumeی پیدا نشد.</p>}</div></CardContent></Card></TabsContent>

      <TabsContent value="topology" className="space-y-4"><Card><CardHeader className="flex-row flex-wrap items-center justify-between gap-3"><div><CardTitle className="flex items-center gap-2"><Waypoints size={17} className="text-primary"/>نقشهٔ ارتباط کانتینرها</CardTitle><CardDescription>عضویت واقعی کانتینرها در Docker network از Engine خوانده می‌شود؛ شبکهٔ مشترک یعنی مسیر ارتباطی ممکن است، نه اینکه الان ترافیکی بین اپ‌ها در جریان باشد.</CardDescription></div><a href="#/app-mesh" className="text-xs font-medium text-primary hover:underline">مدیریت شبکهٔ اپلیکیشن‌ها</a></CardHeader><CardContent className="space-y-3">{data.networks.map((item) => { const members = item.containers || []; const appIds = [...new Set(members.map((member) => member.application_id).filter((id): id is string => !!id))]; const appNames = appIds.map((id) => dockerApps.find((app) => app.id === id)?.name || id.slice(0, 8)); return <article key={item.id} className="rounded-xl border border-border bg-background/35 p-4"><div className="flex flex-wrap items-center gap-2"><span className="grid h-8 w-8 place-items-center rounded-lg bg-primary/[.08] text-primary"><Network size={15}/></span><b dir="ltr" className="font-mono text-xs">{item.name}</b><Badge variant="outline">{item.driver}</Badge>{item.internal && <Badge variant="warning">Internal</Badge>}<span className="text-[10px] text-muted-foreground">{members.length} کانتینر · {appNames.length} اپ ARG</span></div>{item.details_available === false ? <p className="mt-3 text-xs text-amber-200">Docker جزئیات اعضای این شبکه را برنگرداند.</p> : members.length ? <><div className="my-3 flex flex-wrap items-center gap-2 rounded-lg border border-border/60 bg-background/45 p-3"><span className="rounded-lg border border-primary/30 bg-primary/[.07] px-3 py-2 text-xs font-semibold">{item.name}</span><span aria-hidden="true" className="text-primary">⟷</span><div className="flex flex-1 flex-wrap gap-2">{members.map((member) => { const app = member.application_id ? dockerApps.find((candidate) => candidate.id === member.application_id) : undefined; return <div key={member.id} className="min-w-36 rounded-lg border border-border bg-card px-3 py-2"><p dir="ltr" className="text-left font-mono text-[11px] font-semibold">{member.name || member.id.slice(0, 12)}</p><p className="mt-1 text-[10px] text-muted-foreground">{app ? `اپلیکیشن ${app.name}` : 'کانتینر خارج از ARG'}</p><p dir="ltr" className="mt-1 text-left font-mono text-[9px] text-muted-foreground">{member.ipv4 || member.ipv6 || 'IP ثبت نشده'}</p></div> })}</div></div><p className="text-[10px] leading-5 text-muted-foreground">{appNames.length > 1 ? `این شبکه امکان ارتباط بین اپ‌های ${appNames.join('، ')} را فراهم می‌کند.` : appNames.length === 1 && members.filter((member) => member.application_id === appIds[0]).length > 1 ? `چند کانتینر اپ ${appNames[0]} در یک شبکه‌اند و مسیر ارتباط درون همان اپ برقرار است.` : 'برای این شبکه، کانتینرهای متصل در Engine دیده می‌شوند.'}</p></> : <p className="mt-3 rounded-lg border border-dashed border-border p-4 text-center text-xs text-muted-foreground">کانتینری عضو این شبکه نیست.</p>}</article> })}{!data.networks.length && <p className="rounded-xl border border-dashed border-border p-8 text-center text-sm text-muted-foreground">شبکه‌ای برای نمایش وجود ندارد.</p>}</CardContent></Card></TabsContent>
      <TabsContent value="compose" className="space-y-5"><Card><CardHeader><CardTitle className="flex items-center gap-2"><FileCode2 size={18} className="text-primary"/>Docker Compose</CardTitle><CardDescription>برای Pull، بالا آوردن یا توقف پروژه، مسیر فایل را مشخص کن و پیش از اجرا پیامدها را مرور کن.</CardDescription></CardHeader><CardContent><div className="flex flex-wrap items-center justify-between gap-3"><code dir="ltr" className="min-w-0 flex-1 break-all rounded-lg border border-border bg-background/50 p-3 text-left font-mono text-xs">{composeFile}</code><Button disabled={disabled || !data.compose_version} onClick={() => openComposeWizard('compose-up')}><Play size={14}/>پیکربندی و اجرا</Button></div><div className="mt-3 flex flex-wrap gap-2"><Button size="sm" variant="outline" disabled={disabled || !data.compose_version} onClick={() => openComposeWizard('compose-pull')}><Download size={14}/>دریافت imageها</Button><Button size="sm" variant="outline" disabled={disabled || !data.compose_version} onClick={() => openComposeWizard('compose-down')}><Square size={14}/>توقف پروژه</Button></div>{!data.compose_version && <p className="mt-3 text-xs text-amber-200">افزونهٔ Docker Compose در این سرور نصب نیست؛ نصب Docker Engine را بررسی کن.</p>}</CardContent></Card><Card><CardHeader><CardTitle>پروژه‌های شناسایی‌شده</CardTitle><CardDescription dir="ltr">{data.compose_version ? `Docker Compose ${data.compose_version}` : 'Compose unavailable'}</CardDescription></CardHeader><CardContent><div className="space-y-2">{(data.compose_projects || []).map((project, index) => <div key={`${project.Name}-${index}`} className="rounded-xl border border-border bg-background/40 p-3"><div className="flex items-center gap-2"><FileCode2 size={15} className="text-primary"/><b dir="ltr" className="font-mono text-xs">{project.Name || 'project'}</b><Badge variant="outline">{project.Status || 'unknown'}</Badge></div>{project.ConfigFiles && <p dir="ltr" className="mt-2 break-all text-left font-mono text-[10px] text-muted-foreground">{project.ConfigFiles}</p>}</div>)}{!(data.compose_projects || []).length && <p className="rounded-xl border border-dashed border-border p-8 text-center text-sm text-muted-foreground">پروژهٔ فعال Compose شناسایی نشد.</p>}</div></CardContent></Card>
      <Dialog open={composeWizardOpen} onOpenChange={(open) => { if (!busy) { setComposeWizardOpen(open); if (!open) { setComposeWizardStep(0); setComposeDownAcknowledged(false) } } }}><DialogContent className="max-w-xl"><DialogHeader><DialogTitle>اجرای عملیات Docker Compose</DialogTitle><DialogDescription>فایل Compose روی VPS اجرا می‌شود. پیش از ارسال درخواست، تنظیمات و اثر عملیات را مرور کن.</DialogDescription></DialogHeader><div className="space-y-5"><UnifiedStepper currentStep={composeWizardStep} steps={[{ id: 'configure', title: 'تنظیم عملیات', description: 'انتخاب فایل و کار' }, { id: 'review', title: 'بازبینی و اجرا', description: 'بررسی پیامدها' }]}/>{composeWizardStep === 0 ? <div className="space-y-4"><label className="block space-y-2 text-xs"><span>مسیر فایل Compose روی VPS</span><Input value={composeFile} onChange={(event) => setComposeFile(event.target.value)} dir="ltr" placeholder="/opt/project/docker-compose.yml"/><span className="block leading-5 text-muted-foreground">فایل باید از قبل روی سرور وجود داشته باشد. ARG محتوای YAML را در این مرحله تغییر نمی‌دهد.</span></label><label className="block space-y-2 text-xs"><span>عملیات</span><select value={composeAction} onChange={(event) => { setComposeAction(event.target.value as typeof composeAction); setComposeDownAcknowledged(false) }} className="h-10 w-full rounded-lg border border-input bg-background px-3 text-sm"><option value="compose-pull">دریافت imageهای تعریف‌شده</option><option value="compose-up">ایجاد یا به‌روزرسانی سرویس‌ها</option><option value="compose-down">توقف پروژه</option></select></label><div className="flex justify-between gap-2"><Button variant="outline" disabled={!!busy} onClick={() => setComposeWizardOpen(false)}>انصراف</Button><Button disabled={!!busy || !composeFile.trim()} onClick={() => setComposeWizardStep(1)}>بازبینی عملیات</Button></div></div> : <div className="space-y-4"><div className="rounded-xl border border-border bg-background/45 p-3 text-xs"><p className="text-muted-foreground">عملیات انتخاب‌شده</p><p className="mt-1 font-semibold">{composeAction === 'compose-pull' ? 'دریافت imageها' : composeAction === 'compose-up' ? 'ایجاد یا به‌روزرسانی سرویس‌ها' : 'توقف و حذف کانتینرهای پروژه'}</p><code dir="ltr" className="mt-3 block break-all text-left font-mono">{composeFile}</code></div><p className="text-xs leading-5 text-muted-foreground">{composeAction === 'compose-pull' ? 'Docker imageهای جدید را برای این فایل دریافت می‌کند؛ سرویس‌ها در حال اجرا می‌مانند.' : composeAction === 'compose-up' ? 'Docker Compose سرویس‌های فایل را ایجاد یا به‌روزرسانی می‌کند. ممکن است کانتینرها دوباره ساخته شوند.' : 'سرویس‌ها متوقف و کانتینرهای همین پروژه حذف می‌شوند. Volumeهای داده حفظ می‌شوند.'}</p>{composeAction === 'compose-down' && <label className="flex items-start gap-2 rounded-lg border border-amber-500/20 bg-amber-500/[.05] p-3 text-xs leading-5"><input type="checkbox" checked={composeDownAcknowledged} onChange={(event) => setComposeDownAcknowledged(event.target.checked)} className="mt-1 accent-primary"/>متوجه‌ام که سرویس‌های این پروژه از دسترس خارج می‌شوند؛ Volumeها طبق رفتار Compose حفظ می‌شوند.</label>}<div className="flex flex-wrap justify-between gap-2"><Button variant="outline" disabled={!!busy} onClick={() => setComposeWizardStep(0)}>بازگشت</Button><Button variant={composeAction === 'compose-down' ? 'destructive' : 'default'} disabled={!!busy || !composeFile.trim() || composeAction === 'compose-down' && !composeDownAcknowledged} onClick={() => void executeComposeWizard()}>{busy === composeAction ? <LoaderCircle size={14} className="animate-spin"/> : composeAction === 'compose-down' ? <Square size={14}/> : composeAction === 'compose-pull' ? <Download size={14}/> : <Play size={14} />}{busy === composeAction ? 'در حال اجرا…' : 'تأیید و اجرا'}</Button></div></div>}</div></DialogContent></Dialog>
      </TabsContent>
      </Tabs>

      <div className="mt-4 flex flex-wrap items-center justify-between gap-2 text-[11px] text-muted-foreground"><span>Docker CLI: <code dir="ltr">{data.version || '—'}</code> · Engine: <code dir="ltr">{data.server_version || 'offline'}</code></span>{data.installed && <Button size="sm" variant="ghost" disabled={!!busy} onClick={() => void run('uninstall', {}, 'بسته‌های Docker Engine حذف شوند؟ داده‌های /var/lib/docker و volumeها دست‌نخورده می‌مانند.')}><Trash2 size={13}/>حذف بسته‌های Docker</Button>}</div>
    </>}
    {output && <Card className="mt-5"><CardHeader className="pb-2"><CardTitle className="text-sm">گزارش آخرین عملیات</CardTitle></CardHeader><CardContent><pre className="max-h-56 overflow-auto whitespace-pre-wrap break-words rounded-xl bg-[#090d12] p-3 text-left font-mono text-xs text-muted-foreground" dir="ltr">{output}</pre></CardContent></Card>}
    {confirmDialog}
  </>
}

type OptimizationPanelProps = {
  optimization: OptimizationData | null
  loading: boolean
  error: string
  retentionDays: 7 | 30 | 90
  setRetentionDays: (days: 7 | 30 | 90) => void
  refresh: () => void
  run: (action: string, payload?: Record<string, unknown>, confirmation?: string, alreadyConfirmed?: boolean) => Promise<boolean>
  busy: string
  dockerReady: boolean
}

function DockerOptimizationPanel({ optimization, loading, error, retentionDays, setRetentionDays, refresh, run, busy, dockerReady }: OptimizationPanelProps) {
  const dockerCanPrune = dockerReady && optimization?.docker.available === true
  const totalEstimate = optimization
    ? optimization.docker.build_cache_bytes + optimization.docker.images_bytes + optimization.docker.containers_bytes + optimization.arg_cache.reclaimable_bytes + optimization.logs.journal_reclaimable_bytes + optimization.logs.rotated_reclaimable_bytes + optimization.apt_cache_bytes
    : 0
  const runAction = (action: string, message: string, payload: Record<string, unknown> = {}) => void run(action, payload, message)
  return <section className="space-y-4" aria-label="بهینه‌سازی مصرف فضای سرور">
    <Card>
      <CardHeader className="flex-row flex-wrap items-center justify-between gap-3">
        <div><CardTitle className="flex items-center gap-2"><Sparkles size={17} className="text-primary"/>بهینه‌سازی و آزادسازی فضا</CardTitle><CardDescription>مقدارها پیش از حذف از Docker Engine و فایل‌های سرور برآورد می‌شوند؛ هر عملیات جداگانه تأیید می‌گیرد.</CardDescription></div>
        <Button size="sm" variant="outline" disabled={loading || !!busy} onClick={refresh}><RefreshCw size={14} className={loading ? 'animate-spin' : ''}/>محاسبهٔ دوباره</Button>
      </CardHeader>
      <CardContent className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">
        <MetricCard label="برآورد کل قابل آزادسازی" value={optimization ? formatBytes(totalEstimate) : '—'} detail={optimization ? `زمان محاسبه: ${new Date(optimization.measured_at * 1000).toLocaleString('fa-IR')}` : 'در انتظار اندازه‌گیری'} icon={<HardDrive size={18}/>} tone="teal" direction="rtl"/>
        <MetricCard label="Docker build cache" value={optimization ? formatBytes(optimization.docker.build_cache_bytes) : '—'} detail="فقط لایه‌های Build بلااستفاده" icon={<Box size={18}/>} tone="blue" direction="rtl"/>
        <MetricCard label="Cache غیرفعال ARG" value={optimization ? formatBytes(optimization.arg_cache.reclaimable_bytes) : '—'} detail={`Cacheهای mount غیرفعال · ${optimization?.arg_cache.protected_mounts || 0} mount فعال محافظت می‌شود`} icon={<Database size={18}/>} tone="copper" direction="rtl"/>
        <MetricCard label="لاگ قدیمی سرور" value={optimization ? formatBytes(optimization.logs.journal_reclaimable_bytes + optimization.logs.rotated_reclaimable_bytes) : '—'} detail={`قدیمی‌تر از ${retentionDays} روز`} icon={<Activity size={18}/>} tone="warning" direction="rtl"/>
      </CardContent>
    </Card>
    {error && <Alert className="border-rose-400/25 bg-rose-400/[.06]"><CircleAlert size={15}/><AlertDescription>{error}</AlertDescription></Alert>}
    {optimization?.docker.error && <Alert className="border-amber-300/20 bg-amber-300/[.04]"><CircleAlert size={15}/><AlertDescription>برآورد Docker در دسترس نیست: {optimization.docker.error}</AlertDescription></Alert>}
    {optimization?.logs.error && <p className="text-[10px] text-muted-foreground">خواندن اندازهٔ Journal ممکن نشد: {optimization.logs.error}</p>}
    <div className="grid gap-3 lg:grid-cols-2">
      <OptimizationActionCard title="پاک‌سازی Build Cache داکر" description="لایه‌های Build بلااستفاده حذف می‌شوند. کانتینرها و Imageهای فعال دست‌نخورده می‌مانند؛ Build بعدی ممکن است طولانی‌تر شود." bytes={optimization?.docker.build_cache_bytes || 0} icon={Box} disabled={!dockerCanPrune || !!busy} onClick={() => runAction('docker-builder-prune', 'تمام Build cache بلااستفاده پاک شود؟ دادهٔ اجرایی کانتینرها حذف نمی‌شود؛ ساخت‌های بعدی ممکن است کندتر شوند.')} />
      <OptimizationActionCard title="Imageهای بلااستفاده" description="Imageهایی که به کانتینر موجود وابسته نیستند پاک می‌شوند؛ برای اجرای دوباره ممکن است لازم باشد از Registry دریافت شوند." bytes={optimization?.docker.images_bytes || 0} icon={Download} disabled={!dockerCanPrune || !!busy} onClick={() => runAction('image-prune', 'همهٔ Imageهای بلااستفاده حذف شوند؟ Imageهای موردنیاز برای اجرای مجدد باید دوباره دریافت شوند.')} />
      <OptimizationActionCard title="کانتینرهای متوقف‌شده" description="فقط کانتینرهای متوقف و لایهٔ قابل‌نوشتن آن‌ها حذف می‌شوند؛ Volumeهای متصل باقی می‌مانند." bytes={optimization?.docker.containers_bytes || 0} icon={Square} disabled={!dockerCanPrune || !!busy} onClick={() => runAction('docker-container-prune', 'تمام کانتینرهای متوقف‌شده حذف شوند؟ Volumeهای داده حفظ می‌شوند.')} />
      <OptimizationActionCard title="شبکه‌های بلااستفاده" description="شبکه‌هایی که هیچ کانتینری به آن‌ها وصل نیست حذف می‌شوند؛ این مورد فضای کمی آزاد می‌کند اما تنظیمات شبکهٔ باقی‌مانده را ساده می‌کند." bytes={0} icon={Network} disabled={!dockerCanPrune || !!busy} onClick={() => runAction('docker-network-prune', 'همهٔ شبکه‌های Docker بدون اتصال حذف شوند؟')} />
      <OptimizationActionCard title="Cache بلااستفادهٔ ARG S3" description="فقط پوشهٔ Cache مربوط به mountهای unmounted پاک می‌شود. Cacheهای mount فعال از روی وضعیت ARG و mountهای واقعی محافظت می‌شوند." bytes={optimization?.arg_cache.reclaimable_bytes || 0} icon={Database} disabled={!!busy} onClick={() => runAction('arg-cache-prune', 'Cache مربوط به mountهای S3 غیرفعال ARG پاک شود؟ اطلاعات منبع ابری حذف نمی‌شود و Cache هنگام استفادهٔ دوباره بازسازی خواهد شد.')} />
      <div className="rounded-xl border border-border bg-card p-4">
        <div className="flex items-start gap-3"><Activity size={17} className="mt-0.5 text-amber-200"/><div className="min-w-0 flex-1"><h3 className="text-sm font-semibold">لاگ‌های قدیمی سیستم</h3><p className="mt-1 text-xs leading-5 text-muted-foreground">Journalهای آرشیوشده و فایل‌های چرخشی قدیمی‌تر از بازهٔ انتخابی پاک می‌شوند؛ فایل Journal فعال و لاگ جاری نگه داشته می‌شود.</p></div></div>
        <div className="mt-4 flex flex-wrap items-center justify-between gap-3"><div><p className="text-[10px] text-muted-foreground">Journal فعلی: {formatBytes(optimization?.logs.journal_bytes || 0)}</p><p className="mt-1 text-xs font-semibold">برآورد قدیمی‌ها: {formatBytes((optimization?.logs.journal_reclaimable_bytes || 0) + (optimization?.logs.rotated_reclaimable_bytes || 0))}</p></div><div className="flex gap-2"><select aria-label="مدت نگه‌داری لاگ‌ها" value={retentionDays} onChange={(event) => { const value = Number(event.target.value); if (value === 7 || value === 30 || value === 90) setRetentionDays(value) }} className="h-9 rounded-lg border border-input bg-background px-2 text-xs"><option value={7}>نگه‌داری ۷ روز</option><option value={30}>نگه‌داری ۳۰ روز</option><option value={90}>نگه‌داری ۹۰ روز</option></select><Button size="sm" variant="outline" disabled={!!busy} onClick={() => runAction('server-logs-prune', `لاگ‌های آرشیوی قدیمی‌تر از ${retentionDays} روز حذف شوند؟ لاگ‌های جاری حفظ می‌شوند.`, { retention_days: retentionDays })}><Trash2 size={13}/>پاک‌سازی</Button></div></div>
      </div>
      <OptimizationActionCard title="Cache بسته‌های APT" description="فقط فایل‌های بستهٔ دانلودشده پاک می‌شوند. فهرست بسته‌ها و برنامه‌های نصب‌شده باقی می‌مانند." bytes={optimization?.apt_cache_bytes || 0} icon={Download} disabled={!!busy} onClick={() => runAction('apt-cache-clean', 'فایل‌های بستهٔ دانلودشدهٔ APT پاک شوند؟ برنامه‌های نصب‌شده تغییر نمی‌کنند.')} />
      <OptimizationActionCard title="پاک‌سازی ترکیبی Docker" description="Build cache، Imageهای بدون استفاده، کانتینرهای متوقف و شبکه‌های بی‌استفاده را یک‌جا حذف می‌کند. Volumeها حذف نمی‌شوند." bytes={optimization ? optimization.docker.build_cache_bytes + optimization.docker.images_bytes + optimization.docker.containers_bytes : 0} icon={Sparkles} disabled={!dockerCanPrune || !!busy} onClick={() => runAction('system-prune', 'پاک‌سازی ترکیبی Docker انجام شود؟ Build cache، Imageهای بلااستفاده، کانتینرهای متوقف و شبکه‌های خالی حذف می‌شوند؛ Volumeها باقی می‌مانند.')} />
    </div>
    <Alert className="border-amber-300/20 bg-amber-300/[.035]"><CircleAlert size={15}/><AlertDescription>Volumeهای استفاده‌نشده ممکن است داده داشته باشند و در برآورد آزادسازی خودکار شمرده نمی‌شوند؛ برای بررسی دستی به تب Volumeها برو. مقدار واقعی آزادشده ممکن است به‌دلیل لایه‌های مشترک و فایل‌های sparse با برآورد تفاوت داشته باشد.</AlertDescription></Alert>
  </section>
}

function OptimizationActionCard({ title, description, bytes, icon: Icon, disabled, onClick }: { title: string; description: string; bytes: number; icon: typeof HardDrive; disabled: boolean; onClick: () => void }) {
  return <Card><CardContent className="flex h-full flex-col p-4"><div className="flex items-start gap-3"><span className="grid h-8 w-8 shrink-0 place-items-center rounded-lg border border-primary/15 bg-primary/[.05] text-primary"><Icon size={15}/></span><div className="min-w-0 flex-1"><h3 className="text-sm font-semibold">{title}</h3><p className="mt-1 text-xs leading-5 text-muted-foreground">{description}</p></div></div><div className="mt-4 flex flex-wrap items-center justify-between gap-2 border-t border-border/60 pt-3"><span className="text-[10px] text-muted-foreground">برآورد فضای آزادشده</span><span dir="ltr" className="font-mono text-xs font-semibold">{formatBytes(bytes)}</span></div><Button className="mt-3 self-start" size="sm" variant="outline" disabled={disabled} onClick={onClick}><Trash2 size={13}/>اجرای پاک‌سازی</Button></CardContent></Card>
}
